import{_ as a,c as l,o as e,a4 as t}from"./chunks/framework.1PDP1GxW.js";const b=JSON.parse(`{"title":"Joney's blog - 24年01月","description":"","frontmatter":{"title":"Joney's blog - 24年01月"},"headers":[],"relativePath":"shanxing/2024-01.md","filePath":"shanxing/2024-01.md","lastUpdated":null}`),n={name:"shanxing/2024-01.md"},i=t('<h1 id="_2024-1月-关于24年的plan" tabindex="-1">2024-1月-关于24年的Plan <a class="header-anchor" href="#_2024-1月-关于24年的plan" aria-label="Permalink to &quot;2024-1月-关于24年的Plan&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#第一次当伴郎我也学习学习">第一次当伴郎我也学习学习</a></li><li><a href="#永远的planb">永远的PlanB</a></li><li><a href="#程序员的第二曲线">程序员的第二曲线</a></li></ul></nav><h2 id="第一次当伴郎我也学习学习" tabindex="-1">第一次当伴郎我也学习学习 <a class="header-anchor" href="#第一次当伴郎我也学习学习" aria-label="Permalink to &quot;第一次当伴郎我也学习学习&quot;">​</a></h2><p>今年回故乡，我的一个亲戚结婚下（文称呼它为涛叔），让我去当伴郎。从接亲开始 完整的过完了一遍流程。发现原来结婚哈 也并没有我想象中的复杂。但是也不简单哈。我和涛叔 都属于比较内向那种，所以也出了一些插曲 哈哈。 下面我简单聊聊 我们那边的一个整体风俗习惯。</p><ol><li><p>婚礼前一天，男方需要去女方家里送一些猪肉什么的;</p></li><li><p>结婚当前 去新娘家里面，进门第一件事上下聘礼还是礼物什么的🎁的，忘记了 反正是要给的;</p></li><li><p>然后就是等待新娘准备好之后 就开始“红包轰炸”，伴郎的任务就是协助新郎找鞋子;</p></li><li><p>新娘出嫁的时候 新人需要给新娘的爸爸妈妈敬茶，获取其认可;</p></li><li><p>在出新娘家的时候 要放一路的鞭炮🧨，然后在街上遇见人/包括新娘家附近的邻居，见者有份， 要给他们散烟/糖 🍬 以祈求好彩头;</p></li><li><p>然后我们就需要前往 新郎家里面 重复4的步骤，这个时候新娘回把嫁妆也带过去</p></li><li><p>之后就做车去婚礼现场啦（之后的事情就是交给婚庆公司和婚礼主持人啦）</p></li></ol><p>我总以为结婚很复杂，实际上好像也并没有多复杂，很多事情自己不去做/不去经历永远也不知道是怎么一回事。 <strong>未知让人恐惧</strong> 这句话说有道理的。</p><h2 id="永远的planb" tabindex="-1">永远的PlanB <a class="header-anchor" href="#永远的planb" aria-label="Permalink to &quot;永远的PlanB&quot;">​</a></h2><p>我在23年11月被优化掉了。从裁员到现在，我搞清楚了一个非常重要的事情。你永远都需要一个PlanB\\PlanC 总而言之，你需要多套应对事情的策略和方案，永远给自己留下一点儿后路，哪怕是最亲近的人 我认为都需要留下后路（老婆除外，虽然我没有哈哈哈哈😂）。<strong>别人应许你的，永远不要当真</strong></p><h2 id="程序员的第二曲线" tabindex="-1">程序员的第二曲线 <a class="header-anchor" href="#程序员的第二曲线" aria-label="Permalink to &quot;程序员的第二曲线&quot;">​</a></h2><p>年前的一个偶然机会，加入了卡颂的一个课程，觉得蛮有意思的。未来一定会诞生越来越多的超级个体，一个人就是一家公司。一个人也可以大招一个非常优秀的产品。我们运用合适的工具，也可以做到过去一个人做不到的事。</p><p>人生的意义在于体验，年轻人啊，未来说属于你们的！，姑且去尝试多一些，万一成功了怎么办。</p><p>最后附上伟大的教员说的话：“世界是你们的!也是我们的，但是归根结底是你们的。你们青年人朝气蓬勃，好像早晨八九点钟的太阳。希望寄托在你们身上！”</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>致未来10年后的自己：“未来的你呀，已经成家了吧？那个她是否是你希望的人？你是否依然没有忘记自己的梦想？是否依然为之而奋斗和拼搏？，不要被现实打败！如果跌倒就请你再爬起来！只要还活着 就没有什么不行的”</p></div>',13),o=[i];function p(s,r,c,h,_,d){return e(),l("div",null,o)}const f=a(n,[["render",p]]);export{b as __pageData,f as default};
